import {registerCardComponent} from "@pihanga2/core";

import {StepperComponent} from "./stepper.component";
import {STEPPER_ACTION, STEPPER_CARD} from "./stepper.types";

export * from "./stepper.types";

registerCardComponent({
  name: STEPPER_CARD,
  component: StepperComponent,
  // Explicit mapping avoids CamelCase issues: STEPCLICKED → onStepClicked
  // (actionTypesToEvents would produce onStepclicked with lowercase 'c').
  events: {
    onStepClicked: STEPPER_ACTION.STEPCLICKED,
  },
});

import React, {useState} from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import {StepperUI, type StepData} from "@/components/ui/stepper";
import type {StepperEvents, StepperProps} from "./stepper.types";
// Default visual styles — import before component renders so BEM classes are styled.
// Override by targeting the same class names in a stylesheet loaded after this one.
import "./stepper.css";

export const StepperComponent = (
  props: PiCardProps<StepperProps, StepperEvents>,
): React.ReactNode => {
  const {
    steps,
    activeStep: propActiveStep,
    defaultActiveStep = 0,
    selfManaged = false,
    orientation = "horizontal",
    size = "md",
    showContent = false,
    className,
    cardName,
    onStepClicked,
  } = props;

  // Internal state used only when selfManaged=true.
  // Initialised from propActiveStep (if given) or defaultActiveStep.
  const [managedStep, setManagedStep] = useState<number>(
    propActiveStep ?? defaultActiveStep,
  );

  // Resolve the effective active step:
  //   - selfManaged  → use internal state
  //   - controlled   → use the prop (fall back to 0 if not set)
  const activeStep = selfManaged ? managedStep : (propActiveStep ?? 0);

  // Map StepItem[] → StepData[] (UI primitive only needs serialisable fields
  // plus an optional pre-rendered React node for custom labels).
  const stepData: StepData[] = steps.map((step) => ({
    id: step.id,
    title: step.title,
    description: step.description,
    optional: step.optional,
    // If a labelCard is specified, render it here and pass as `labelNode`.
    // The UI primitive will display it instead of the default title/description.
    labelNode: step.labelCard ? (
      <Card cardName={step.labelCard} parentCard={cardName} />
    ) : undefined,
  }));

  function handleStepClick(stepIndex: number, stepId: string) {
    if (selfManaged) {
      setManagedStep(stepIndex);
    }
    // Dispatch Pihanga event when the callback is wired (it may be absent for
    // inline / anonymous card declarations that have no registered reducer).
    if (typeof onStepClicked === "function") {
      onStepClicked({stepIndex, stepId});
    }
  }

  /**
   * Render a card ref for the active step's content (vertical mode only).
   * We look up the original `steps` array to get the `contentCard` reference.
   */
  function renderStepContent(stepIndex: number): React.ReactNode {
    if (!showContent || orientation !== "vertical") return null;
    const step = steps[stepIndex];
    if (!step?.contentCard) return null;
    return <Card cardName={step.contentCard} parentCard={cardName} />;
  }

  return (
    <div data-pihanga={cardName}>
      <StepperUI
        steps={stepData}
        activeStep={activeStep}
        orientation={orientation}
        size={size}
        className={className}
        onStepClick={handleStepClick}
        renderStepContent={renderStepContent}
      />
    </div>
  );
};

/* ============================================================
   pi-stepper — default visual styles
   src/cards/shadcn/stepper/stepper.css

   All visual properties live here so consumers can override
   individual rules by targeting the same BEM class names in
   a stylesheet loaded after this one (or by replacing this
   file entirely).

   Structural / layout Tailwind classes stay in the JSX and
   are not repeated here.

   Color tokens: the project uses Tailwind v4 with oklch values.
   Variables like --primary, --border etc. are full oklch() color
   values — use them directly with var(--primary), NOT with
   hsl(var(--primary)) which would be invalid in this setup.
   ============================================================ */

/* ── CSS size variables (override per stepper or globally) ─── */
.pi-stepper {
  --pi-stepper-indicator-size-sm: 1.5rem;
  /* 24 px */
  --pi-stepper-indicator-size-md: 2rem;
  /* 32 px */
  --pi-stepper-indicator-size-lg: 2.5rem;
  /* 40 px */
  --pi-stepper-indicator-size: var(--pi-stepper-indicator-size-md);
  --pi-stepper-connector-thickness: 2px;
  --pi-stepper-connector-min-height: 1.5rem;
  /* vertical mode */
  --pi-stepper-label-max-width: 6rem;
  /* horizontal mode */
}

/* ── Size modifiers ─────────────────────────────────────────── */
.pi-stepper--sm {
  --pi-stepper-indicator-size: var(--pi-stepper-indicator-size-sm);
}

.pi-stepper--md {
  --pi-stepper-indicator-size: var(--pi-stepper-indicator-size-md);
}

.pi-stepper--lg {
  --pi-stepper-indicator-size: var(--pi-stepper-indicator-size-lg);
}

/* ──────────────────────────────────────────────────────────────
   Indicator (step icon / circle)

   Tailwind classes in stepper.tsx provide WORKING defaults:
     bg-primary / text-primary-foreground / ring-* / border-*
   Override them here by raising specificity one level (e.g. add
   the parent class) or by using !important if needed.
   ────────────────────────────────────────────────────────────── */

/* Base indicator — transitions only (no colors; Tailwind handles defaults) */
.pi-stepper__indicator {
  transition:
    background-color 200ms ease,
    border-color 200ms ease,
    color 200ms ease,
    outline-color 200ms ease;
}

/* To override the active indicator colour, use e.g.:
     .pi-stepper__indicator--active { background-color: var(--destructive); }
   The var() tokens are direct oklch values in this project. */

.pi-stepper__indicator--clickable {
  cursor: pointer;
}

.pi-stepper__indicator--clickable:hover {
  opacity: 0.8;
}

.pi-stepper__indicator--static {
  cursor: default;
}

/* ── Connector (line between steps) ─────────────────────────── */
.pi-stepper__connector {
  transition: background-color 300ms ease;
}

/* Vertical connector segment */
.pi-stepper__connector--vertical {
  min-height: var(--pi-stepper-connector-min-height);
}

/* ── Label title ─────────────────────────────────────────────── */
.pi-stepper__label-title {
  transition: color 200ms ease;
}

/* ── Vertical step content slot ──────────────────────────────── */
.pi-stepper__step-content {
  /* no special styles needed — spacing set via Tailwind in JSX */
}

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
} from "@pihanga2/core";

export const STEPPER_CARD = "shad/stepper";

export const Stepper = createCardDeclaration<StepperProps, StepperEvents>(
  STEPPER_CARD,
);

export const STEPPER_ACTION = registerActions(STEPPER_CARD, ["stepClicked"]);

export const onStepperStepClicked = createOnAction<StepperStepClickedEvent>(
  STEPPER_ACTION.STEPCLICKED,
);

// ─── Step definition ─────────────────────────────────────────────────────────

/**
 * A single step in the stepper.
 */
export type StepItem = {
  /** Unique identifier used in events. */
  id: string;

  /** Short label shown below/beside the step indicator. */
  title: string;

  /** Optional secondary text shown under the title. */
  description?: string;

  /**
   * If true, an "(Optional)" suffix is appended to the title.
   * Mirrors the MUI Joy UI `optional` prop.
   */
  optional?: boolean;

  /**
   * Optional Pihanga card rendered **instead of** the default title/description
   * text label.  Useful for rich labels (icons, custom markup, etc.).
   * The card receives no extra props — use `memo` in its own declaration if
   * it needs to read from state.
   */
  labelCard?: PiCardRef;

  /**
   * A card ref rendered as the body of this step when it is active
   * and the stepper is in `"vertical"` orientation with `showContent: true`.
   */
  contentCard?: PiCardRef;
};

// ─── Card props ───────────────────────────────────────────────────────────────

export type StepperProps = {
  /** Ordered list of step definitions. */
  steps: StepItem[];

  /**
   * 0-based index of the currently active step (controlled mode).
   * Steps before this index are rendered as "completed";
   * steps after are "upcoming".
   *
   * Required in controlled mode (`selfManaged: false`).
   * Used as the initial value in self-managed mode when provided
   * (otherwise defaults to `defaultActiveStep ?? 0`).
   */
  activeStep?: number;

  /**
   * Initial active step used only in self-managed mode (`selfManaged: true`).
   * Ignored in controlled mode.
   * @default 0
   */
  defaultActiveStep?: number;

  /**
   * When `true`, the component manages its own `activeStep` state internally.
   * Clicking a step immediately advances the indicator without waiting for the
   * host application to update the `activeStep` prop via a reducer.
   * The `onStepClicked` event is still dispatched on each click.
   *
   * When `false` (default), `activeStep` fully controls the display.
   * @default false
   */
  selfManaged?: boolean;

  /**
   * Layout orientation.
   * - `"horizontal"` (default): steps flow left-to-right with labels below.
   * - `"vertical"`: steps stack top-to-bottom with labels/content to the right.
   */
  orientation?: "horizontal" | "vertical";

  /**
   * Visual size of the step indicators.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";

  /**
   * When `true` and `orientation === "vertical"`, the active step's
   * `contentCard` is rendered inline beneath its label.
   * @default false
   */
  showContent?: boolean;

  /** Additional Tailwind classes applied to the root element. */
  className?: string;
};

// ─── Events ───────────────────────────────────────────────────────────────────

export type StepperStepClickedEvent = {
  /** 0-based index of the clicked step. */
  stepIndex: number;
  /** The `id` of the clicked step definition. */
  stepId: string;
};

export type StepperEvents = {
  /** Fired when the user clicks on a step indicator. */
  onStepClicked: StepperStepClickedEvent;
};
